import React, { useState, useEffect } from 'react';
import GlobalStyle from './styles/GlobalStyle';
import styled from 'styled-components';

import Header from './components/Header';
import Equipment from './components/Equipment';
import EquipmentSearch from './components/EquipmentSearch';
import GearAdvice from './components/GearAdvice';
import SelectedSidebar from './components/SelectedSidebar';
import TrainingTips from './components/TrainingTips';

// Mock data in case trainingTipsData is missing
const trainingTipsData = [
  { id: 1, tip: "Keep hydrated during long rides" },
  { id: 2, tip: "Check tire pressure before every ride" },
  { id: 3, tip: "Wear appropriate clothing for weather conditions" },
];

const MainContainer = styled.div`
  display: flex;
  justify-content: space-between;
  margin: 20px auto;
  max-width: 1200px;
`;

const ContentArea = styled.div`
  flex: 2;
  padding-right: 20px;
`;

const SidebarArea = styled.div`
  flex: 1;
  padding-left: 20px;
`;

function App() {
  const [selectedEquipment, setSelectedEquipment] = useState([]);
  const [filteredEquipment, setFilteredEquipment] = useState([]);
  const [equipmentData, setEquipmentData] = useState([]);

  // Fetch data from Flask backend
  useEffect(() => {
    const fetchData = async () => {
      try {
        const response = await fetch('http://localhost:5000/api/competitivecyclist');
        const data = await response.json();
        setEquipmentData(data);
        setFilteredEquipment(data);
      } catch (error) {
        console.error('Error fetching data:', error);
      }
    };

    fetchData();
  }, []);

  const handleSelect = (item) => {
    const itemWithPrice = {
      ...item,
      price: item.price || '$100', // Example pricing for items without a price
    };
    setSelectedEquipment((prev) =>
      prev.find((i) => i.id === itemWithPrice.id)
        ? prev.filter((i) => i.id !== itemWithPrice.id)
        : [...prev, itemWithPrice]
    );
  };

  const handleSearch = (searchTerm) => {
    if (searchTerm === '') {
      setFilteredEquipment(equipmentData);
    } else {
      setFilteredEquipment(
        equipmentData.filter((item) =>
          item.Name.toLowerCase().includes(searchTerm.toLowerCase())
        )
      );
    }
  };

  const handleRemoveItem = (id) => {
    setSelectedEquipment(selectedEquipment.filter((item) => item.id !== id));
  };

  return (
    <>
      <GlobalStyle />
      <Header />
      <GearAdvice />

      <MainContainer>
        <ContentArea>
          <EquipmentSearch onSearch={handleSearch} />
          <Equipment equipment={filteredEquipment} handleSelect={handleSelect} />
          <TrainingTips tips={trainingTipsData} />
        </ContentArea>

        <SidebarArea>
          <SelectedSidebar selectedItems={selectedEquipment} removeItem={handleRemoveItem} />
        </SidebarArea>
      </MainContainer>
    </>
  );
}

export default App;
